bsc-skill() { if [ "$#" -gt 0 ]; then b="${BSC_BIN:-}"; if [ -n "$b" ]; then "$b" skill "$@"; return $?; fi; echo "bsc-skill: library CLI unavailable (BSC_BIN unset)" >&2; return 127; fi; l="${BSC_SKILL_LOG:-}"; [ -z "$l" ] && return 0; j="$(cat)"; sn="$(printf '%s' "$j" | tr '\t\n' '  ' | __bsc_jstr skill_name | cut -c1-120)"; ev="$(printf '%s' "$j" | tr '\t\n' '  ' | __bsc_jstr hook_event_name | cut -c1-120)"; ts="$(date -u +%Y-%m-%dT%H:%M:%SZ)"; __bsc_logline "$l" '%s\t%s\t%s\t%s\n' "$ts" "${BSC_AUDIT_PANE:-?}" "$ev" "$sn"; return 0; }
